/* ==========================================================================
   TEKNIX MONOREPO — NOTIFICATION ICONS & ASSET MAPPER (@teknix/notifications)
   Camada compartilhada de mapeamento de assets 3D de alta fidelidade
   Redimensionados via sips (64px, alpha preservado) e empacotados como Data URIs
   ========================================================================== */

export const NOTIFICATION_ASSETS = {
  carrinhoNovaVenda: "data:image/png;base64,",
  pixAprovado: "data:image/png;base64,",
  cartaoAprovado: "data:image/png;base64,",
  pagamentoAprovado: "data:image/png;base64,",
  boleto: "data:image/png;base64,",
  pedidoSeparado: "data:image/png;base64,",
  etiquetaGerada: "data:image/png;base64,",
  pedidoEnviado: "data:image/png;base64,",
  pedidoEntregue: "data:image/png;base64,",
  notaFiscal: "data:image/png;base64,",
  mensagemChat: "data:image/png;base64,",
  alertaAtencao: "data:image/png;base64,",
  alertaErro: "data:image/png;base64,",
  prazoVencimento: "data:image/png;base64,",
  usuarioConfiguracao: "data:image/png;base64,"
} as const

export type NotificationIconKey =
  | "sale"
  | "cart"
  | "pix"
  | "payment_approved"
  | "credit_card"
  | "boleto"
  | "order_separated"
  | "label_created"
  | "order_shipped"
  | "order_delivered"
  | "invoice"
  | "message"
  | "warning"
  | "error"
  | "due_date"
  | "user"

export const NOTIFICATION_ICON_MAP: Record<NotificationIconKey, string> = {
  sale: NOTIFICATION_ASSETS.pagamentoAprovado,
  cart: NOTIFICATION_ASSETS.pagamentoAprovado,
  pix: NOTIFICATION_ASSETS.pixAprovado,
  payment_approved: NOTIFICATION_ASSETS.pagamentoAprovado,
  credit_card: NOTIFICATION_ASSETS.cartaoAprovado,
  boleto: NOTIFICATION_ASSETS.boleto,
  order_separated: NOTIFICATION_ASSETS.pedidoSeparado,
  label_created: NOTIFICATION_ASSETS.etiquetaGerada,
  order_shipped: NOTIFICATION_ASSETS.pedidoEnviado,
  order_delivered: NOTIFICATION_ASSETS.pedidoEntregue,
  invoice: NOTIFICATION_ASSETS.notaFiscal,
  message: NOTIFICATION_ASSETS.mensagemChat,
  warning: NOTIFICATION_ASSETS.alertaAtencao,
  error: NOTIFICATION_ASSETS.alertaErro,
  due_date: NOTIFICATION_ASSETS.prazoVencimento,
  user: NOTIFICATION_ASSETS.usuarioConfiguracao
}

export interface NotificationIconResolveInput {
  module?: string | null
  type?: string | null
  eventType?: string | null
  title?: string | null
  message?: string | null
  metadata?: Record<string, any> | null
}

/**
 * Mapeia inteligentemente qualquer evento/notificação TEKNIX para a chave do ícone oficial correspondente.
 */
export function resolveNotificationIconKey(item: NotificationIconResolveInput): NotificationIconKey | null {
  const mod = String(item.module || "").toLowerCase()
  const typ = String(item.type || "").toLowerCase()
  const evt = String(item.eventType || "").toLowerCase()
  const title = String(item.title || "").toLowerCase()
  const msg = String(item.message || "").toLowerCase()
  const combined = `${mod} ${typ} ${evt} ${title} ${msg}`

  // 1. Erros e cancelamentos explícitos
  if (typ === "error" || evt.includes("cancel") || evt.includes("fail") || combined.includes("recusad") || combined.includes("falha") || combined.includes("cancelad")) {
    return "error"
  }

  // 2. Pix
  if (mod === "pix" || combined.includes("pix")) {
    return "pix"
  }

  // 3. Boleto
  if (combined.includes("boleto")) {
    return "boleto"
  }

  // 4. Cartão / Pagamento
  if (combined.includes("cartão") || combined.includes("cartao") || combined.includes("crédito") || combined.includes("credito")) {
    return "credit_card"
  }
  if (mod === "payment" || evt.includes("payment") || evt.includes("paid") || combined.includes("pagamento aprovado")) {
    return "payment_approved"
  }

  // 5. Envios e Logística
  if (combined.includes("entregue") || evt.includes("delivered")) {
    return "order_delivered"
  }
  if (combined.includes("separad") || combined.includes("separação") || combined.includes("separacao")) {
    return "order_separated"
  }
  if (combined.includes("etiqueta") || combined.includes("label")) {
    return "label_created"
  }
  if (mod === "shipment" || mod === "envio" || evt.includes("shipped") || combined.includes("enviad") || combined.includes("rastreio") || combined.includes("trânsito")) {
    return "order_shipped"
  }

  // 6. Nota Fiscal / Fiscal
  if (mod === "invoice" || mod === "fiscal" || combined.includes("nota fiscal") || combined.includes("nfe") || combined.includes("danfe")) {
    return "invoice"
  }

  // 7. Venda / Pedido
  if (mod === "sale" || mod === "order" || evt.includes("order.created") || evt.includes("product.purchased") || evt.includes("marketplace.sale") || combined.includes("nova venda") || combined.includes("novo pedido")) {
    return "sale"
  }

  // 8. Mensagens / Chat
  if (mod === "message" || mod === "question" || mod === "chat" || combined.includes("mensagem") || combined.includes("pergunta")) {
    return "message"
  }

  // 9. Prazos e Vencimentos
  if (combined.includes("vencimento") || combined.includes("prazo") || combined.includes("expir")) {
    return "due_date"
  }

  // 10. Estoque baixo / Alerta amarelo
  if (mod === "stock" || combined.includes("estoque") || typ === "warning" || combined.includes("aviso")) {
    return "warning"
  }

  // 11. Usuário / Perfil / Conta
  if (mod === "user" || mod === "customer" || evt.includes("user.") || combined.includes("usuário") || combined.includes("usuario") || combined.includes("cadastro") || combined.includes("senha") || combined.includes("perfil")) {
    return "user"
  }

  return null
}

/**
 * Retorna diretamente o Data URI do ícone aprovado ou null se deve usar o fallback (SVG/Lucide).
 */
export function resolveNotificationIcon(item: NotificationIconResolveInput): string | null {
  const key = resolveNotificationIconKey(item)
  if (!key) return null
  return NOTIFICATION_ICON_MAP[key] || null
}
